import{_ as i,c as t,o as s,aj as a}from"./chunks/framework.Id7s26SP.js";const g=JSON.parse('{"title":"Configuring Primitive Services","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/configuring-primitive-services.md","filePath":"getting-started/configuring-primitive-services.md"}'),n={name:"getting-started/configuring-primitive-services.md"};function o(r,e,d,l,c,h){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="configuring-primitive-services" tabindex="-1">Configuring Primitive Services <a class="header-anchor" href="#configuring-primitive-services" aria-label="Permalink to “Configuring Primitive Services”">​</a></h1><p>Primitive stores your app’s service configuration on the server: sign-in methods, server functions, prompts, integrations, database schemas, and more. Manage it in the Admin Console or keep it as TOML files in your repository.</p><p>There are two equivalent ways to manage that configuration:</p><ol><li><strong>The <a href="https://admin.primitiveapi.com" target="_blank" rel="noreferrer">Admin Console</a></strong> — interactive and visual. Best for exploring, testing, and one-off changes.</li><li><strong>TOML files in your repo, synced via the CLI</strong> — configuration as code. Best for anything you want versioned, reviewed, reproduced across environments, or managed by an AI coding agent.</li></ol><p>Both edit the same underlying configuration. Most teams explore in the console and commit the result as TOML.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to “Environments”">​</a></h2><p>A project usually targets more than one app — a development app for day-to-day coding, a production app for your customers. The CLI&#39;s named environments bind a server and app together so every command (including <code>config pull</code> and <code>config push</code>) knows which app it&#39;s talking to, and each environment gets its own isolated config directory. See <a href="./primitive-cli.html#project-configuration-and-environments">Project Configuration and Environments</a>.</p><p>In a web app, which Primitive environment a build resolves is independent of its Vite mode (the <code>.env.&lt;mode&gt;</code> file of app-behavior keys). When a mode&#39;s keys are only correct against one backend, pin the pair with <code>VITE_EXPECTED_PRIMITIVE_ENV=&lt;name&gt;</code> in that mode&#39;s <code>.env</code> file: a run that resolves a different environment then fails at startup instead of using the wrong app. See <a href="./deploying-to-production.html#pinning-a-mode-to-a-primitive-environment">Pinning a mode to a Primitive environment</a>.</p><h2 id="console-or-code" tabindex="-1">Console or Code? <a class="header-anchor" href="#console-or-code" aria-label="Permalink to “Console or Code?”">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Console</th><th>TOML + CLI</th></tr></thead><tbody><tr><td>Exploring and testing</td><td>Preferred — visual, interactive</td><td>Works but less convenient</td></tr><tr><td>Version-controlled config</td><td>—</td><td>Preferred</td></tr><tr><td>Quick one-off changes</td><td>Convenient</td><td>Convenient</td></tr><tr><td>AI agent automation</td><td>—</td><td>Preferred — agents speak CLI</td></tr><tr><td>CI/CD pipelines</td><td>—</td><td>Preferred — scriptable</td></tr></tbody></table><h2 id="the-sync-loop" tabindex="-1">The Sync Loop <a class="header-anchor" href="#the-sync-loop" aria-label="Permalink to “The Sync Loop”">​</a></h2><p><code>primitive config</code> round-trips your app&#39;s configuration between the server and a directory of TOML files:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # create the directory structure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # download current server config as TOML</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... edit files locally ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # see what would change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # apply your changes to the server</span></span></code></pre></div><p>The config directory is <code>primitive/&lt;env&gt;/</code> — one isolated slot per environment, and the only directory any <code>config</code> command reads or writes. The lookup walks up from where you run the command, so in an app with <a href="./multi-client.html">several clients</a> the configuration lives once at the repository root and every client directory resolves it.</p><p>The files live in your repo, so configuration changes ride the same workflow as code: branches, diffs, reviews, rollbacks. <code>config push</code> runs a local preflight over the tree before it applies anything — an error there aborts the push with no changes applied — and reports the file and entity behind any failure. See <a href="#what-a-push-guarantees">What a push guarantees</a> for what that preflight checks and what it leaves to the server.</p><p><strong>Preview before you push.</strong> <code>primitive config diff</code> shows which entities would be created, changed, or removed; <code>primitive config push --dry-run</code> walks the full push and reports the same outcome without writing anything. Both answer from the comparison push itself acts on, so a clean <code>diff</code> means <code>push</code> has nothing to apply; <a href="#what-diff-compares">What diff compares</a> covers how each difference is reported.</p><p><code>config pull</code> rewrites only the files that differ from the server. A file <code>config diff</code> reports as in sync stays exactly as you wrote it, including its comments, key order, and explicit defaults, so <code>git diff</code> after a pull shows only real server changes. The pull summary reports how many files it wrote and how many it left unchanged.</p><p>Every <code>config pull</code> snapshots the config directory before writing, so a pull that overwrites local edits is recoverable:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # list available snapshots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # restore the most recent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --snapshot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # restore a specific one</span></span></code></pre></div><p>Snapshots are local CLI state, kept out of version control and pruned after 28 days. <code>revert</code> replaces the config directory with the snapshot — run <code>primitive config diff</code> afterwards to see where the restored files stand relative to the server.</p><h2 id="toml-is-the-only-write-path" tabindex="-1">TOML Is the Only Write Path <a class="header-anchor" href="#toml-is-the-only-write-path" aria-label="Permalink to “TOML Is the Only Write Path”">​</a></h2><p>To change configuration with the CLI, edit its TOML file and run <code>primitive config push</code>. Use the commands below to discover fields, create files, and edit scalar values.</p><p>Four commands cover authoring without leaving the terminal:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fields</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # the type&#39;s TOML keys, types, required, defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-intake</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # scaffold functions/order-intake.toml from defaults</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function/order-intake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function.description=&quot;Order intake&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # edit one scalar in place</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> function/order-intake</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # apply just that object</span></span></code></pre></div><ul><li><strong><code>config fields &lt;type&gt;</code></strong> lists a configuration type&#39;s TOML keys with their types, whether they&#39;re required, and their defaults — the way to discover the field surface. <code>--json</code> prints it for tooling, and <code>primitive config fields --help</code> lists every type it accepts.</li><li><strong><code>config create &lt;type&gt; &lt;key&gt;</code></strong> writes <code>&lt;key&gt;.toml</code> in that type&#39;s directory, filled in from the type&#39;s defaults. It is local only — nothing reaches the server until you push.</li><li><strong><code>config set &lt;object&gt; &lt;path&gt;=&lt;value&gt;...</code></strong> sets one or more scalars in an existing file, preserving comments and key order. <code>&lt;object&gt;</code> is <code>&lt;type&gt;/&lt;key&gt;</code>, <code>app</code>, or <code>vars</code>. Also local only. Tables and arrays are edited in the file directly.</li><li><strong><code>config push --only &lt;selector&gt;[,...]</code></strong> applies just the named objects instead of the whole tree. Selectors are <code>&lt;type&gt;/&lt;key&gt;</code>, <code>app</code>, or <code>var/&lt;key&gt;</code>. Everything else about push — validation, conflict detection, <code>--dry-run</code>, <code>--force</code>, <code>--prune</code> — behaves the same.</li></ul><p><code>set</code> plus <code>push --only</code> is the scripting path: two commands, no here-document, no temporary file.</p><p>Delete a configuration object by removing its file and pushing with <code>--prune</code>. Deleting a metadata category leaves its stored values unreachable; delete those values first if you need them removed.</p><p><strong>Structured values are native TOML tables.</strong> Where a config surface takes a structured value — a function&#39;s or prompt&#39;s <code>inputSchema</code> and <code>outputSchema</code>, a prompt&#39;s <code>providerConfig</code>, a database type&#39;s <code>autoPopulatedFields</code>, a metadata category&#39;s <code>schema</code> — write it as nested TOML tables. The same fields also accept single-line JSON text, which the server treats identically, and <code>config pull</code> keeps whichever form a file already uses.</p><p><strong>What is not configuration stays interactive.</strong> Secrets (<code>primitive secrets set</code>) never go in a file. Resources whose creation mints a server id — <code>primitive apps create</code>, <code>databases create</code>, <code>collections create</code>, <code>groups create</code> — are created with a command, then configured in TOML. Data operations (<code>databases records</code>, <code>documents records</code>, <code>metadata set</code>) and every read or test command (<code>list</code>, <code>get</code>, <code>diff</code>, <code>test</code>, <code>execute</code>) are unaffected. Availability and retirement are the two recurring cases of this, covered next.</p><h2 id="what-lives-in-the-config-directory" tabindex="-1">What Lives in the Config Directory <a class="header-anchor" href="#what-lives-in-the-config-directory" aria-label="Permalink to “What Lives in the Config Directory”">​</a></h2><p>One subdirectory per kind of configuration:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>primitive/&lt;env&gt;/</span></span>
<span class="line"><span>  app.toml                        # App settings</span></span>
<span class="line"><span>  vars.toml                       # Config vars (non-secret key/value store)</span></span>
<span class="line"><span>  prompts/*.toml                  # Managed prompts</span></span>
<span class="line"><span>  prompts/{key}.tests/*.toml      # Prompt test cases</span></span>
<span class="line"><span>  integrations/*.toml             # External API integrations</span></span>
<span class="line"><span>  integrations/{key}.tests/*.toml # Integration test cases</span></span>
<span class="line"><span>  functions/*.toml                # Server function definitions</span></span>
<span class="line"><span>  functions/{key}/**              # Function sources (the entry its TOML names)</span></span>
<span class="line"><span>  functions/primitive-db-types.d.ts  # Generated: this app&#39;s database types</span></span>
<span class="line"><span>  functions/primitive-functions.d.ts # Generated: the function SDK&#39;s own types</span></span>
<span class="line"><span>  functions/tsconfig.json         # Scaffolded: wires both into your editor</span></span>
<span class="line"><span>  database-type-configs/*.toml    # Database types: schemas, rule set, triggers</span></span>
<span class="line"><span>  blob-buckets/*.toml             # Blob bucket definitions</span></span>
<span class="line"><span>  email-templates/*.toml          # Email template overrides</span></span>
<span class="line"><span>  rule-sets/*.toml                # Access rule sets</span></span>
<span class="line"><span>  group-type-configs/*.toml       # Group type configuration</span></span>
<span class="line"><span>  collection-type-configs/*.toml  # Collection type configuration</span></span>
<span class="line"><span>  metadata-category-configs/*.toml # Resource metadata category configs</span></span></code></pre></div><p>Every feature page in these docs that shows a TOML block — <a href="./server-functions.html">Server Functions</a>, <a href="./prompts.html">Prompts</a>, <a href="./api-integrations.html">API Integrations</a>, <a href="./working-with-databases.html">Working with Databases</a>, <a href="./blobs-and-files.html">Blobs and Files</a>, <a href="./resource-metadata.html">Resource Metadata</a> — is describing one of these files. Define the entity in TOML, <code>primitive config push</code>, and it&#39;s live.</p><p><code>vars.toml</code> round-trips your app&#39;s <a href="./app-secrets.html#config-vars">config vars</a> the same way <code>app.toml</code> round-trips app settings — a flat table of non-secret key/value pairs, written by <code>config pull</code> and applied by <code>config push</code>.</p><p>Credentials never go in these files: config that needs an API key references it as <code>{{secrets.KEY}}</code>, with the value stored server-side. See <a href="./app-secrets.html">App Secrets</a>.</p><h3 id="app-settings" tabindex="-1">App Settings (<code>app.toml</code>) <a class="header-anchor" href="#app-settings" aria-label="Permalink to “App Settings (app.toml)”">​</a></h3><p>Edit <code>app.toml</code>, then use <code>primitive config push --only app</code> to apply app settings. Inspect changes with <code>primitive config diff --only app</code>. The main sections are:</p><ul><li><code>[app]</code> — <code>name</code>, <code>mode</code>, <code>baseUrl</code>, <code>waitlistEnabled</code>, <code>waitlistNotifyAdmins</code>, <code>allowedDomains</code>, <code>testAccountBaseEmails</code>, <code>largeDocumentWindowDays</code> (how many days this app&#39;s <a href="./working-with-documents.html#large-documents">large documents</a> may be written offline before a client goes read-only — 1–14; omit it to take the deployment&#39;s window, 7 days unless the deployment says otherwise), <code>rootDocumentFormat</code> (set it to <code>2</code> to create each new user&#39;s root document as a <a href="./working-with-documents.html#root-documents-as-large-documents">large document</a>; omit it, or set <code>1</code>, for an ordinary root document. Root documents that already exist keep their format), <code>protected</code> (marks the app as live with real users; only the app&#39;s console owner can set or clear it — anyone else&#39;s push that would change it is refused)</li><li><code>[auth]</code> — <code>googleOAuthEnabled</code>, <code>emailSignInEnabled</code>, <code>passkeyEnabled</code>, <code>passkeyUserVerification</code>, <code>appleSignInEnabled</code>, <code>appleAudiences</code>, <code>emailRedirectUris</code>, <code>[auth.google.clients.&lt;type&gt;]</code> Google client entries, and <code>[auth.passkeys]</code> relying-party config</li><li><code>[cors]</code> — <code>mode</code>, <code>allowedOrigins</code>, <code>allowCredentials</code>, <code>allowedMethods</code>, <code>allowedHeaders</code>, <code>exposedHeaders</code>, <code>maxAge</code></li><li><code>[invitations]</code> — <code>enabled</code>, <code>limit</code> (whether members may send invitations and the per-member cap)</li></ul><p><strong>Removing a setting clears it or restores its default.</strong> Keep explicit values for settings you need to remain disabled, especially <code>emailSignInEnabled = false</code>. Pull before editing an existing app so the file starts with its current configuration.</p><p><code>[app].name</code> and <code>[app].mode</code> are required. Unknown keys and invalid values are rejected before changes are applied.</p><p>The <code>[auth]</code> fields — the Google client map, the email sign-in allow-list, and passkeys — follow the same TOML rules as everything above; see <a href="./authentication.html">Authentication</a> for what each field does and its error codes.</p><p>Change these settings by editing <code>app.toml</code> and pushing it — there is no command that sets an app setting directly (see <a href="#toml-is-the-only-write-path">TOML Is the Only Write Path</a>):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app.mode=invite-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span></span></code></pre></div><p>Use <code>primitive config fields app</code> to discover accepted settings. See <a href="./authentication.html">Authentication</a> for sign-in configuration examples.</p><h3 id="functions-directory" tabindex="-1">The Functions Directory <a class="header-anchor" href="#functions-directory" aria-label="Permalink to “The Functions Directory”">​</a></h3><p>Author <code>functions/&lt;key&gt;.toml</code> and its TypeScript entry file. Push generates the files below from your schemas and configuration:</p><table tabindex="0"><thead><tr><th>File under <code>functions/</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>primitive-db-types.d.ts</code></td><td>Database model types.</td></tr><tr><td><code>primitive-functions.d.ts</code></td><td>Function SDK types.</td></tr><tr><td><code>primitive-function-types.d.ts</code></td><td>Function input and output types.</td></tr><tr><td><code>primitive-document-types.d.ts</code></td><td>Document model types.</td></tr><tr><td><code>primitive-prompt-types.d.ts</code></td><td>Prompt output types.</td></tr><tr><td><code>primitive-document-schema.generated.toml</code></td><td>Schema copy used when the project has no <code>models/models.toml</code>.</td></tr><tr><td><code>generated/&lt;key&gt;.generated.ts</code></td><td>Typed client invokers.</td></tr><tr><td><code>tsconfig.json</code></td><td>TypeScript settings for function code.</td></tr></tbody></table><p>Do not edit generated declarations. You can customize <code>tsconfig.json</code>; push preserves your settings while maintaining required type mappings. Use <code>primitive functions codegen --check</code> to detect stale files in CI.</p><p>See <a href="./server-functions.html">Server Functions</a> for declarations and <a href="./server-functions-invoking.html#triggers">triggers</a>.</p><h3 id="test-case-identity" tabindex="-1">Test Case Identity <a class="header-anchor" href="#test-case-identity" aria-label="Permalink to “Test Case Identity”">​</a></h3><p>Prompt and integration cases live in <code>&lt;key&gt;.tests/&lt;case&gt;.toml</code>. The filename identifies the case; renaming it renames the registered case while preserving its history. A case names the configuration it runs under and its judge prompt by <code>configName</code>, <code>evaluatorPromptKey</code>, and <code>evaluatorConfigName</code>, so the file works unchanged in every app.</p><p><strong>Push before running tests.</strong> Test commands use registered server cases, not local files. Remove a case file and push with <code>--prune</code> to delete it. <code>config diff</code> shows which cases are new, modified, removed, or invalid.</p><h2 id="email-templates" tabindex="-1">Email Templates <a class="header-anchor" href="#email-templates" aria-label="Permalink to “Email Templates”">​</a></h2><p>Primitive sends transactional email on your app&#39;s behalf — the sign-in email, document and collection share notices, waitlist and invitation messages. Each kind has a built-in default, and you can override any of them with your own subject and body. Your app can also register custom types to send app-specific mail such as order confirmations or receipts.</p><p>The built-in types are <code>email-sign-in</code>, <code>document-share</code>, <code>document-share-deferred</code>, <code>collection-share</code>, <code>collection-share-deferred</code>, <code>waitlist-invite</code>, <code>waitlist-signup-notification</code>, <code>admin-invite</code>, <code>app-invite</code>, <code>access-request-created</code>, and <code>access-request-resolved</code>. A server function&#39;s <code>ctx.api.email.send</code> can send any of these, or a custom kebab-case type you register.</p><p>Each type exposes template variables — <code>{{code}}</code>, <code>{{expiryMinutes}}</code> and the optional <code>{{magicLink}}</code> for <code>email-sign-in</code>, and so on — that Primitive substitutes at send time. A custom subject and/or HTML and text body overrides the built-in default; deleting the override restores it. Overrides live in the config directory as <code>email-templates/&lt;emailType&gt;.toml</code>, a <code>[template]</code> table naming the type it overrides (<code>emailType</code> and <code>subject</code> required, <code>htmlBody</code> and <code>textBody</code> optional):</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># primitive/dev/email-templates/email-sign-in.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">emailType = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;email-sign-in&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">subject = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Sign in to MyApp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">htmlBody = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;p&gt;Your code: &lt;strong&gt;{{code}}&lt;/strong&gt; (expires in {{expiryMinutes}} minutes){{#if magicLink}}&lt;br&gt;Or tap to sign in: {{magicLink}}{{/if}}&lt;/p&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">textBody = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Your code: {{code}}{{#if magicLink}} — or sign in: {{magicLink}}{{/if}}&quot;</span></span></code></pre></div><p>It&#39;s authored and applied like any other configuration:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email-template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email-sign-in</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # scaffold email-templates/email-sign-in.toml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... edit subject, html, text ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> email-template/email-sign-in</span></span></code></pre></div><p>Use <code>email-sign-in</code> for sign-in email. Keep <code>{{code}}</code> and <code>{{expiryMinutes}}</code> in its body; put the optional link inside <code>{{#if magicLink}}…{{/if}}</code>.</p><p>See <a href="./authentication.html#email-sign-in-one-email-one-or-two-credentials">Email Sign-In</a> for which parts of the <code>email-sign-in</code> override are removable (the link block) and which aren&#39;t (<code>{{code}}</code>).</p><p>Delete the file and run <code>primitive config push --prune</code> to drop the override and go back to the built-in default. See <a href="./primitive-cli.html#email-templates">Email Templates</a> for the read commands — listing types and override status, viewing a type&#39;s current template and variables, and sending a test email.</p><h2 id="status-is-server-owned" tabindex="-1">Availability (<code>status</code>) Is Server-Owned <a class="header-anchor" href="#status-is-server-owned" aria-label="Permalink to “Availability (status) Is Server-Owned”">​</a></h2><p>Use <code>disable</code> and <code>enable</code> to stop or resume functions, integrations, and prompts. Availability is separate from their configuration, so pushing a fix does not re-enable a disabled service.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">function-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> functions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">function-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Do not add an object’s availability <code>status</code> to TOML. A prompt configuration’s <code>[[configs]] status</code> is different: it retires an individual named configuration and remains in the file.</p><h2 id="archive-vs-prune" tabindex="-1">Retiring an Object: Archive vs Prune <a class="header-anchor" href="#archive-vs-prune" aria-label="Permalink to “Retiring an Object: Archive vs Prune”">​</a></h2><ul><li><strong>Archive</strong> a function, integration, or prompt to stop using it while retaining its history and key. Use <code>primitive &lt;noun&gt; archive &lt;id&gt;</code>.</li><li><strong>Prune</strong> to permanently delete a managed object and free its key. Remove its file, then run <code>primitive config push --prune</code>.</li></ul><p>An archived object cannot be enabled. To reuse its key, pull the configuration, prune the archived object, then add the file again and push. Pruning destroys the object; use it only when you no longer need that history.</p><p>Both actions request confirmation. Use <code>--yes</code> only when the intended deletion has already been reviewed, including in automation.</p><h2 id="push-and-diff-in-detail" tabindex="-1">Push and Diff in Detail <a class="header-anchor" href="#push-and-diff-in-detail" aria-label="Permalink to “Push and Diff in Detail”">​</a></h2><p>The sync loop above is all most changes need. This section is the precise contract behind it — what <code>diff</code> compares, which failures stop a push, and how deletions and out-of-band edits reconcile — for when a push surprises you.</p><h3 id="what-diff-compares" tabindex="-1">What diff compares <a class="header-anchor" href="#what-diff-compares" aria-label="Permalink to “What diff compares”">​</a></h3><p><code>config diff</code> compares local files with current server configuration. <code>config push --dry-run</code> previews a push without applying changes.</p><table tabindex="0"><thead><tr><th>Result</th><th>Action</th></tr></thead><tbody><tr><td>New or modified</td><td>Review the change, then push.</td></tr><tr><td>Server drift</td><td>Pull the server change, or deliberately overwrite with <code>--force</code>.</td></tr><tr><td>Conflict</td><td>Reconcile both edits before pushing.</td></tr><tr><td>Invalid</td><td>Fix the named field or file.</td></tr><tr><td>Not compared</td><td>Resolve the read failure before relying on the preview.</td></tr><tr><td>Remote only</td><td>Pull to manage it locally, or review whether a managed object should be pruned.</td></tr></tbody></table><p>A local file can recreate an object deleted on the server. Remove that file if the deletion was intentional. Function builds and checks requiring live app state can still fail during an actual push.</p><h3 id="what-a-push-guarantees" tabindex="-1">What a push guarantees <a class="header-anchor" href="#what-a-push-guarantees" aria-label="Permalink to “What a push guarantees”">​</a></h3><p>A push has two stages:</p><ol><li><strong>Preflight</strong> checks local files, types, and declared constraints. For a <code>function</code>, this includes its entry, capabilities, and trigger settings. Any preflight failure stops the push before changes are applied.</li><li><strong>Apply</strong> sends changes to the server. This can fail because of app state, such as a missing secret, a limit, or a key conflict. Earlier successful changes remain applied; there is no rollback.</li></ol><p>Read the reported file and error, resolve the problem, then push again. Reapplying successful changes is safe. Use the field names and types shown by <code>primitive config fields &lt;type&gt;</code>; unrecognized keys are errors.</p><h3 id="deletions-and-cleared-fields" tabindex="-1">Deletions, Cleared Fields, and Out-of-Band Edits <a class="header-anchor" href="#deletions-and-cleared-fields" aria-label="Permalink to “Deletions, Cleared Fields, and Out-of-Band Edits”">​</a></h3><p>These operations have different effects:</p><ul><li><strong>Remove a managed field:</strong> the next push clears it or restores its default.</li><li><strong>Remove an object’s file:</strong> ordinary push leaves the server object in place. Add <code>--prune</code> to delete it permanently.</li><li><strong>Delete on the server:</strong> pull removes the previously managed local file. Uncommitted edits are preserved; <code>--no-prune</code> preserves all local files.</li><li><strong>Edit both locally and on the server:</strong> push reports a conflict. Pull takes server values; <code>--force</code> makes local values win.</li></ul><p>Prune applies only to objects already managed by the sync tree. It reports objects that changed remotely or remain referenced instead of deleting them. Review the plan before confirming.</p><p>Keep <code>.sync-state.json</code> with your configuration. If a server-side deletion leaves a stale entry and push reports an update to a missing object, remove only that object’s state entry and push again to recreate it. Pull also reconciles state, but overwrites server-backed files, so preserve local edits first.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><strong><a href="./primitive-cli.html">Primitive CLI</a></strong> — Full CLI reference, environments, and sync details</li><li><strong><a href="./admin-console.html">Admin Console</a></strong> — The interactive view of the same configuration</li><li><strong><a href="./server-functions.html">Server Functions</a></strong> — Server-side logic, authored and pushed from the same tree</li></ul>`,87)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
